--
-- Table structure for table `qrtz_job_task`
--

DROP TABLE IF EXISTS `qrtz_job_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qrtz_job_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(128) NOT NULL COMMENT '任务名称',
  `cron` varchar(64) DEFAULT NULL COMMENT 'cron表达式',
  `status` char(24) DEFAULT NULL COMMENT '作业状态',
  `remark` varchar(256) NOT NULL DEFAULT '' COMMENT '备注',
  `params` varchar(512) DEFAULT '' COMMENT '执行参数',
  `method` varchar(128) NOT NULL COMMENT '要调用的方法',
  `job_name` varchar(128) NOT NULL COMMENT '作业名称',
  `concurrent` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否并发',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `qrtz_job_task_job_name_uindex` (`job_name`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='作业任务';
