CREATE TABLE `sys_region` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) DEFAULT NULL COMMENT '行政代码',
  `name` varchar(255) DEFAULT NULL COMMENT '名称',
  `pid` int NOT NULL COMMENT '父id',
  `first_letter` varchar(10) DEFAULT NULL COMMENT '首字母',
  `level` int NOT NULL COMMENT '城市等级',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2463 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='行政区域';
